-- ProvaCerta: PISM II. 20 questões objetivas por dia; redação adaptada para estudo.

-- Textos integrais nos cadernos UFJF; explicações autorais.

-- Gabaritos revisados preservados: II 2024 dia 1 Q11 C/D; III 2025 dia 1 Q11 C/E e Q15 B/C.

-- III 2026 dia 2 Q17 anulada: A/B/C/D/E representa ponto automático, inclusive em branco.

-- As objetivas do módulo III são comuns às quatro áreas; discursivas não incluídas.

-- Execute o arquivo inteiro no SQL Editor. Reexecutável; IDs e demais provas preservados.

begin;

alter table public.questions add column if not exists explanation text;

alter table public.questions drop constraint if exists questions_answer_check;

alter table public.questions add constraint questions_answer_check check (answer ~ '^[A-E](/[A-E])*$');

