insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Língua Portuguesa', 'Em biografias é comum a utilização de tempos verbais nos pretéritos do indicativo. No entanto, ocorrem variações em função do conteúdo temático, da intenção comunicativa dos escritores e de seus estilos autorais de produção. Sabendo disso, releia um trecho do texto II e responda à questão. “O relato tão pessoal de Quarto de Despejo continua relevante até hoje. O diário de Carolina traz um ponto de vista com pouco espaço na sociedade e, por consequência, na literatura. Já na ocasião de sua publicação, jornalistas e escritores destacaram a denúncia social expressa em suas páginas a partir de descrições pungentes sobre a miséria e os sonhos dos moradores da favela do Canindé.” (3º parágrafo) A alternativa que apresenta a classificação e a análise CORRETA do uso do tempo verbal utilizado preponderantemente neste fragmento é:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto II: apresentação biográfica de Djamila Ribeiro, com informações sobre formação, atuação e produção intelectual. Leia o original no caderno.', null, '["pretérito mais que perfeito do indicativo, uma vez que se relatam ações ocorridas em um tempo anterior à publicação da biografia.", "presente do indicativo, de modo a destacar o ponto de vista de Carolina Maria de Jesus por meio do discurso direto.", "presente do indicativo, uma vez que apresenta uma análise da obra de Carolina de Jesus, e não um relato da sua história.", "presente histórico, com intuito de trazer atualidade a ações ocorridas há um tempo e relatadas na biografia.", "pretérito imperfeito do indicativo, pois é realizada uma descrição dos efeitos da obra de Carolina Maria de Jesus na sociedade."]'::jsonb, 'C', 'Gabarito oficial: C. A biografia combina informações sobre a trajetória da autora com avaliações de sua produção e relevância.' from public.exams where slug='pism-ii-2024-dia-1'

