insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Língua Portuguesa', 'Por meio de diversos relatos ao longo do livro Quarto de Despejo: diário de uma favelada, Carolina Maria de Jesus tematiza a fome, a ponto de poder-se dizer que esta é uma personagem da obra. O trecho retirado do texto III que exemplifica esse processo de personificação é:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto III: trecho de Quarto de despejo, de Carolina Maria de Jesus, sobre fome, pobreza e procura de alimentos. As alternativas foram resumidas, preservando a figura de linguagem cobrada.', null, '["A fome também é professora.", "No lixo foram encontrados alimentos.", "As crianças recolhem alimentos descartados.", "A fome não escolhe apenas um lugar.", "Pessoas buscam alimento e lenha no lixo."]'::jsonb, 'A', 'Gabarito oficial: A. A fome recebe uma ação humana: ensinar. Essa personificação aparece em “A fome também é professora”.' from public.exams where slug='pism-ii-2024-dia-1'

