insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Língua Portuguesa', 'Dentre os títulos e subtítulos anteriores, aquele que melhor exemplifica o tema central do relato de Carolina Maria de Jesus no trecho de Quarto de Despejo: diário de uma favelada, texto III, é o:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Manchetes resumidas: I — Carolina inspira novos autores negros; II — Cidinha lê trechos de Quarto de despejo; III — combater a fome como desafio nacional; IV — a fome atinge proporcionalmente mais lares chefiados por pessoas pretas e pardas; V — manifesto à mulher negra. Consulte os títulos originais no caderno.', null, '["Manchete I.", "Manchete II.", "Manchete III.", "Manchete IV.", "Manchete V."]'::jsonb, 'D', 'Gabarito oficial: D. A manchete IV associa a incidência da fome à raça de quem chefia os domicílios, evidenciando a desigualdade racial.' from public.exams where slug='pism-ii-2024-dia-1'

