insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 5, 'Língua Portuguesa', 'A defesa de Conceição Evaristo, de manutenção de marcas de variação linguística na obra de Carolina Maria de Jesus, indica uma concepção que', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto IV: Conceição Evaristo comenta diferenças entre língua culta e expressão popular, questionando a desvalorização de usos socialmente marcados. Leia o trecho original no caderno.', null, '["converge com os princípios da gramática do cotidiano, compreendendo a língua como um sistema baseado em regras imutáveis.", "contrapõe o oral e o escrito, defendendo a correção do texto em respeito aos modos como cada pessoa se apropria da língua.", "contesta as normas gramaticais e os letramentos da autora, reconhecendo a língua portuguesa como diversificada.", "considera a diversidade da língua, defendendo o uso da informalidade no texto como um erro da norma padrão.", "compreende a língua como um fenômeno social e histórico, de modo que valoriza as variedades populares."]'::jsonb, 'E', 'Gabarito oficial: E. A língua varia histórica e socialmente. A crítica de Conceição Evaristo valoriza a expressão popular e questiona a imposição de uma única variedade como legítima.' from public.exams where slug='pism-ii-2024-dia-1'

