insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Geografia', 'Observe o gráfico abaixo: Fonte: https://www.cptnacional.org.br/publicacao?task=download.send&id=14209&catid=75&m=0 (Adaptado). Acesso em 02 jun, 2023. Considerando a ampliação da fronteira agrícola nomeada como Matopiba, assinale a alternativa CORRETA:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-6.png', '["O aumento do preço da terra na fronteira do Matopiba, como demonstrado no gráfico, amplia sua produtividade, pois aumenta os recursos a serem reinvestidos na área.", "A expansão da fronteira do Matopiba tem possibilitado uma ampliação da produção de alimentos para consumo interno da população brasileira, notável pela ampliação do preço das terras da região.", "A expansão da fronteira do Matopiba amplia os conflitos pela terra devido ao aumento do preço da terra, demonstrada pelo gráfico, fator de expulsão dos pequenos produtores agrícolas.", "A grilagem de terras ocorre, em grande medida, nas áreas de expansão das fronteiras agrícolas, pois os pequenos agricultores se organizam para retomá-las, por meio da grilagem, ao serem expulsos de suas terras.", "A fronteira agrícola do Matopiba tem pouca relação com o crescimento do preço da terra, pois o estado da Bahia é o menos importante da região, sendo esse aumento explicado pelos conflitos agrários especificamente do ano de 2023."]'::jsonb, 'C', 'Gabarito oficial: C. A expansão agrícola do Matopiba valoriza terras e intensifica conflitos fundiários, com pressão sobre pequenos produtores e comunidades tradicionais.' from public.exams where slug='pism-ii-2024-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Geografia', 'Observe as informações abaixo: Fonte: https://www.poder360.com.br/internacional/saiba-quais-paises-são-osprincipais-responsaveis-pelas-mudancas-climaticas/. Acesso em 02 jun ,2023. Considerando o processo de industrialização em âmbito mundial, é CORRETO afirmar que:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-7.png', '["A alteração da produção industrial fordista para a produção flexível impulsionou a migração das sedes industriais para os países periféricos, intensificando suas emissões de gás carbônico.", "A primeira e a segunda Revolução Industrial ocorreram nos atuais países mais ricos, que recentemente têm se desindustrializado e, devido a isso, têm reduzido suas taxas de emissão de gás carbônico.", "Embora a emissão de gás carbônico pelos países menos ricos seja equivalente ao emitido pelos países ricos, aqueles vêm ampliando suas emissões devido à intensa industrialização que, ainda hoje, ocorre em seus territórios.", "A concentração da emissão de gás carbônico nos países ricos tem origem nas primeiras Revoluções Industriais que, mesmo com a produção flexível, mantém seus altos índices de consumo e a concentração das sedes das indústrias tecnológicas.", "Os vinte e três países mais ricos são responsáveis pela emissão de 50% do gás carbônico do mundo, devido, principalmente, às emissões ocorridas entre 1850 e 1950; após esta data as emissões desses países vêm se reduzindo drasticamente."]'::jsonb, 'D', 'Gabarito oficial: D. Países industrializados desde a primeira Revolução Industrial acumulam grande participação histórica nas emissões de CO₂, ligada à produção e ao consumo.' from public.exams where slug='pism-ii-2024-dia-1'

