insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Geografia', 'Considerando as desigualdades de cor/raça no Brasil e os setores da economia, observe o gráfico abaixo: Gráfico – Brasil – População ocupada por cor ou raça segundo os grupos de atividade – 2017 Fonte: https://www.poder360.com.br/internacional/saiba-quais-paises-são-os-principais-responsaveis-pelas-mudancas-climaticas/. Acesso em 02 jun, 2023. Assinale a alternativa CORRETA:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-8.png', '["O setor secundário da economia é o que apresentava a maior desigualdade na quantidade de pessoas brancas em relação às pessoas pretas e pardas ocupando os postos de trabalho.", "O setor terciário da economia é o que apresentava a menor desigualdade na quantidade de pessoas brancas em relação às pessoas pretas e pardas ocupando os postos de trabalho.", "Os setores primário e terciário da economia tinham em seus postos de trabalho a maior quantidade de pessoas pretas e pardas em relação à quantidade de pessoas brancas que os ocupavam.", "Os serviços domésticos, setor primário da economia, apresentavam a maior desigualdade na quantidade de pessoas brancas em relação às pessoas pretas e pardas nos postos de trabalho.", "Nos setores primário e terciário sempre foram onde se concentraram os postos de trabalho formais e de maior valorização na economia brasileira, embora a presença de pessoas brancas neles seja menor."]'::jsonb, 'C', 'Gabarito oficial: C. O gráfico mostra maior participação de trabalhadores negros e pardos no setor primário e em atividades do setor terciário, expressando desigualdades ocupacionais.' from public.exams where slug='pism-ii-2024-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Geografia', 'A pandemia de Covid-19 promoveu grandes alterações sociodemográficas na população brasileira. Segundo dados oficiais, foram mais de 700.000 mortes, o que gerou um significativo aumento na proporção das mortes em relação aos nascimentos. Fonte: https://veja.abril.com.br/brasil/; Acesso em 02 jun, 2023 De acordo com os dados demográficos no período da pandemia, é CORRETO afirmar que:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-9.png', '["A diminuição da relação entre natalidade e mortalidade durante a pandemia acelerou uma tendência que já existia na transição demográfica brasileira.", "As mortes decorrentes do Coronavírus assolaram todo o Brasil, independentemente das desigualdades socioespaciais existentes ao longo do território.", "O aumento da mortalidade em 2020, associada à Covid-19, gerou uma queda permanente na expectativa de vida da população brasileira.", "A proporção entre natalidade e mortalidade em 2020 promoveu uma taxa de reposição negativa da população brasileira durante a pandemia.", "Em termos absolutos, houve uma redução transitória na população brasileira devido ao aumento da mortalidade durante o período pandêmico."]'::jsonb, 'A', 'Gabarito oficial: A. O aumento da mortalidade diminuiu a relação entre nascimentos e mortes, acentuando temporariamente uma tendência de redução do crescimento vegetativo já existente na transição demográfica brasileira. Não implica queda permanente da expectativa de vida nem redução absoluta da população.' from public.exams where slug='pism-ii-2024-dia-1'

