insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Geografia', 'Uma reportagem discute a expansão privada do saneamento e a menor atratividade econômica de pequenos municípios. Que interpretação relaciona esse cenário às desigualdades de acesso?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto jornalístico resumido para estudo. Consulte a notícia e seus dados completos no caderno oficial.', null, '["As novas regras democratizam o acesso aos serviços de saneamento no Brasil ao garantir a gratuidade do serviço à população de baixa renda.", "A falta de investimentos públicos gerou uma queda nos índices de atendimento dos serviços de saneamento no Brasil nas últimas três décadas.", "O novo marco segue uma tendência mundial de privatização dos serviços de saneamento, como ocorre, por exemplo, na França e na Alemanha.", "A falta de interesse do mercado em investir em municípios pequenos e distantes dos grandes centros tende a agravar as desigualdades já existentes.", "As diretrizes do novo marco regulatório priorizam a distribuição de água tratada, que é o serviço de saneamento mais deficitário no Brasil."]'::jsonb, 'D', 'Gabarito oficial: D. Municípios pequenos podem oferecer menor retorno ao investimento privado em saneamento, ampliando desigualdades no acesso aos serviços.' from public.exams where slug='pism-ii-2024-dia-1'

