insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Matemática', 'Uma porta abre até 120°. Quando está totalmente aberta, a distância entre A, na extremidade da porta, e B, na guarnição, é 153 cm. Usando √3 ≈ 1,7, qual a largura aproximada da porta, em centímetros?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-11.png', '["51.", "76.", "87.", "90.", "126."]'::jsonb, 'C/D', 'Gabarito oficial: C/D. O gabarito após recursos aceita C e D. Pela geometria, AB = 2L·sen(60°) ≈ 1,7L; como AB = 153 cm, L ≈ 90 cm, alternativa D. A alternativa C, 87 cm, também foi aceita oficialmente, sem que o documento do gabarito apresente justificativa.' from public.exams where slug='pism-ii-2024-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Matemática', 'Considere uma progressão geométrica de termos positivos cujo 1º termo é igual à razão e o 15º termo é 2. Qual é o 75º termo da progressão?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["32", "64", "256", "512", "1024"]'::jsonb, 'A', 'Gabarito oficial: A. Se o primeiro termo e a razão são q, o 15º termo é q¹⁵ = 2. O 75º termo é q⁷⁵ = (q¹⁵)⁵ = 32.' from public.exams where slug='pism-ii-2024-dia-1'

