insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Matemática', 'Para produzir a caixa de um brinquedo, dois tetraedros regulares e iguais são unidos por uma face de modo que coincidam perfeitamente. Quando a caixa está pronta, a distância entre os vértices não unidos dos dois tetraedros é de 20 cm. A quantidade de plástico, em centímetros quadrados, utilizada para cobrir a superfície externa da caixa pronta é', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["150√3 cm²", "200√3 cm²", "225√3 cm²", "450√3 cm²", "600√3 cm²"]'::jsonb, 'C', 'Gabarito oficial: C. Cada tetraedro tem altura 10 cm. Como h² = 2a²/3, a² = 150. A superfície externa reúne seis faces triangulares: 6·a²√3/4 = 225√3 cm².' from public.exams where slug='pism-ii-2024-dia-1'

