insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 14, 'Matemática', 'Um ângulo α está no segundo quadrante e sen α = 3/4. Qual é o valor de tg α?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["−3√7/7", "−√7/3", "−√7/4", "√7/4", "3√7/7"]'::jsonb, 'A', 'Gabarito oficial: A. No segundo quadrante o cosseno é negativo: cos α = −√(1−9/16) = −√7/4. Logo, tg α = (3/4)/(−√7/4) = −3√7/7.' from public.exams where slug='pism-ii-2024-dia-1'

