insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Matemática', 'João começou a trabalhar como motorista em uma empresa de aplicativos. No primeiro dia de trabalho realizou 7 viagens. A partir do segundo dia, a cada dia, fez 4 viagens a mais que no dia anterior. Em qual dia de trabalho o número total de viagens realizadas desde o primeiro dia chegará a 375?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["10º", "13º", "20º", "25º", "34º"]'::jsonb, 'B', 'Gabarito oficial: B. As viagens formam uma PA de primeiro termo 7 e razão 4: Sₙ=n(2n+5). Ao final do 12º dia são 348 viagens; no 13º, 403. Assim, o 13º é o primeiro dia em que o total ultrapassa 375, conforme o gabarito B. Ressalva: não há dia inteiro com soma exatamente 375, pois a equação Sₙ=375 tem raiz positiva n=12,5; a expressão original chegará a 375 é imprecisa.' from public.exams where slug='pism-ii-2024-dia-1'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'Química', 'O excesso de nutrientes como nitrogênio, fósforo e potássio em rios e lagos causa o processo de eutrofização, que consiste no crescimento de microorganismos e algas que diminuem a quantidade de oxigênio dissolvido na água, podendo levar à mortandade de peixes. Estes elementos químicos são originados de várias fontes, como esgoto doméstico, contendo dejetos e excesso de detergentes, lixo orgânico descartado sem os cuidados necessários e adubos inorgânicos utilizados em grandes áreas de lavoura. Entre as possíveis soluções para resolver o problema da eutrofização, assinale a INADEQUADA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["A coleta correta do esgoto doméstico e industrial, evitando a disposição direta em corpos d’água.", "O descarte de resíduos sólidos, como lixo doméstico e rejeitos industriais, em aterros sanitários.", "O tratamento do esgoto coletado em estações de tratamento, através de processos físico-químicos.", "O tratamento químico direto de corpos d’água poluídos, como rios e lagos .", "O uso de adubos orgânicos nas lavouras, para a minimização dos processos de contaminação de solos e água."]'::jsonb, 'D', 'Gabarito oficial: D. Adicionar diretamente produtos químicos ao rio não resolve a origem da eutrofização e pode agravar a contaminação. As medidas adequadas reduzem a entrada de nutrientes e tratam efluentes.' from public.exams where slug='pism-ii-2024-dia-1'

