insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'Química', 'A água do mar contém MgCl₂ a 0,05 mol/L. Qual massa desse sal pode ser obtida de 1000 L? Use Mg = 24,2 g/mol e Cl = 35,5 g/mol.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["0,95 kg", "2,92 kg", "4,76 kg", "58,5 kg", "95,3 kg"]'::jsonb, 'C', 'Gabarito oficial: C. Em 1000 L a 0,05 mol/L há 50 mol de MgCl₂. A massa molar é 24,2+2·35,5 = 95,2 g/mol. A massa é 4760 g = 4,76 kg.' from public.exams where slug='pism-ii-2024-dia-1'

