insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'Química', 'Três cilindros de mesmo volume, à mesma temperatura, contêm respectivamente 10 kg de O₂, 10 kg de H₂ e 10 kg de CO. Qual afirmação está correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["CO tem maior pressão por conter mais átomos.", "H₂ tem maior pressão porque sua massa molar é menor.", "O₂ tem maior pressão porque sua massa molar é maior.", "H₂ e O₂ têm a mesma pressão por serem diatômicos.", "Os três têm a mesma pressão por conterem a mesma massa."]'::jsonb, 'B', 'Gabarito oficial: B. Para mesma massa, temperatura e volume, p = nRT/V é maior no gás de menor massa molar. H₂, com 2 g/mol, tem mais mols que O₂ e CO.' from public.exams where slug='pism-ii-2024-dia-1'

