insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'Química', 'Observe a estrutura do oseltamivir. Analise: I — quatro carbonos são sp²; II — existem três ligações π; III — os carbonos ligados a nitrogênio são sp; IV — há carbonos terciários e quaternários. Quais afirmativas estão corretas?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-1-questao-19.png', '["(I) e (II)", "(II) e (III)", "(III) e (IV)", "(I) e (IV)", "(II) e (IV)"]'::jsonb, 'A', 'Gabarito oficial: A. A estrutura tem quatro carbonos sp² e três ligações π: duas em carbonilas e uma na ligação C=C. Não há nitrogênio sp nem carbono quaternário, portanto somente I e II estão corretas.' from public.exams where slug='pism-ii-2024-dia-1'

