insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'Química', 'Na reação CH₄(g)+Cl₂(g) → CH₃Cl(g)+HCl(g), considere energias de dissociação, em kcal/mol: C–H = 105; Cl–Cl = 58; C–Cl = 85; H–Cl = 103. Qual afirmação descreve a troca de energia?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["A reação ocorre com absorção de energia, por isso é considerada endotérmica.", "A reação ocorre com absorção de energia, por isso é considerada exotérmica.", "A reação ocorre com liberação de energia, por isso é considerada endotérmica.", "A reação ocorre com liberação de energia, por isso é considerada exotérmica.", "A reação ocorre sem absorção e sem liberação de energia."]'::jsonb, 'D', 'Gabarito oficial: D. ΔH = ligações rompidas − ligações formadas = (105+58)−(85+103) = −25 kcal/mol. A cloração é exotérmica.' from public.exams where slug='pism-ii-2024-dia-1'

