insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 2, 'Literaturas', 'Ainda sobre o texto de Carlos Drummond de Andrade, o sujeito poético depara-se com uma objeção expressa pelo seguinte exemplo de recurso de linguagem:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

O texto discute hábitos e diferenças pessoais; a questão analisa o efeito do conectivo “contudo”. Textos integrais no caderno oficial.', null, '["Reiteração do pronome indefinido “todos”.", "O uso do superlativo em “a morte é igualíssima”.", "A gradação de adjetivos negativos em “cruéis, piedosas ou indiferentes”.", "A mobilização de conectivo em “Contudo, o homem não é igual a nenhum outro [...]”.", "O uso do item lexical “ímpar” como único adjetivo no último verso."]'::jsonb, 'D', 'Gabarito oficial: D. O conectivo “contudo” introduz oposição ao conteúdo anterior, marcando uma objeção.' from public.exams where slug='pism-ii-2024-dia-2'

