insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 3, 'Literaturas', 'O poema Irene do Céu, do escritor Manuel Bandeira, apresenta como um de seus temas a negritude e suas implicações, situado em um país de histórico escravocrata e racista. A partir da leitura do poema, é possível afirmar:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Poema Irene no céu, de Manuel Bandeira: Irene é uma mulher negra representada como boa e humilde; sua entrada no céu é imaginada em diálogo com São Pedro. Textos integrais no caderno oficial.', null, '["Os atributos de Irene descritos no poema foram motivadores para sua entrada no céu.", "A menção a um São Pedro bonachão revela uma moralidade cristã que mascara o racismo na terra.", "Irene é descrita no poema pelo seu caráter agentivo de luta pela liberdade.", "O sujeito poético coloca-se de forma neutra acerca da relação entre Irene e São Pedro.", "O qualificador “sempre de bom humor” não pressupõe razões para irritabilidade da personagem."]'::jsonb, 'B', 'Gabarito oficial: B. A representação de Irene combina subordinação social e uma compensação religiosa imaginada, permitindo discutir o racismo e a idealização da personagem.' from public.exams where slug='pism-ii-2024-dia-2'

