insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 4, 'Literaturas', 'O poema de Cristiane Sobral apresenta, assim como o poema de Manuel Bandeira, a presença de uma protagonista feminina. Em uma perspectiva comparativa, é possível afirmar que:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Compare a caracterização de Irene, de Bandeira, à voz poética de Não vou mais lavar os pratos, de Cristiane Sobral, que afirma sua autonomia e identidade. Textos integrais no caderno oficial.', null, '["Irene e a “preta guerreira” coabitam o mesmo tempo e espaço nos poemas.", "O processo de interdiscursividade entre os poemas se justifica no tema da violência explicitada nos textos.", "A entrada no céu no poema de Bandeira equivaleria semanticamente ao “pé na porta da casa grande” em Sobral.", "O bom humor como um qualificador de Irene é perpetuado na literatura contemporânea tal como no poema de Sobral.", "A passividade de Irene em Bandeira contrasta com a voz empoderada do sujeito poético de Sobral."]'::jsonb, 'E', 'Gabarito oficial: E. O contraste opõe a postura passiva atribuída a Irene à afirmação de autonomia e identidade da voz poética de Cristiane Sobral.' from public.exams where slug='pism-ii-2024-dia-2'

