insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 6, 'Biologia', 'Uma característica comum nas espécies vegetais é o ciclo de vida com alternância de gerações ou metagênese, em que há a alternância de organismos haploides (n) e diploides (2n), sendo que em briófitas o gametófito é a fase', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["dominante e o esporófito é efêmero, ao contrário do que acontece em pteridófitas.", "dominante e o esporófito é efêmero, o mesmo que acontece em pteridófitas.", "dominante e o esporófito é também dominante, ao contrário do que acontece em pteridófitas.", "efêmera e o esporófito é dominante, ao contrário do que acontece em pteridófitas.", "efêmera e o esporófito é dominante, como acontece em pteridófitas."]'::jsonb, 'A', 'Gabarito oficial: A. Nas briófitas predomina o gametófito, e o esporófito é dependente. Nas pteridófitas predomina o esporófito, com gametófito reduzido.' from public.exams where slug='pism-ii-2024-dia-2'

