insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 7, 'Biologia', 'Um dos aspectos que varia entre os grupos animais é a sustentação de seu corpo, ou seja, o seu esqueleto interno ou externo. Sobre este assunto, assinale a alternativa INCORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["Os artrópodes apresentam um exoesqueleto constituído principalmente por quitina.", "Os equinodermos apresentam um exoesqueleto constituído principalmente por placas de carbonato de cálcio.", "Os nematoides apresentam um esqueleto hidrostático constituído principalmente por líquido que se localiza na sua cavidade corporal.", "Os poríferos apresentam um endoesqueleto constituído principalmente por espículas de calcário ou sílica.", "Os tetrápodes apresentam um endoesqueleto constituído principalmente por tecido ósseo."]'::jsonb, 'B', 'Gabarito oficial: B. Equinodermos possuem endoesqueleto de placas calcárias. A alternativa B é incorreta por classificá-lo como exoesqueleto.' from public.exams where slug='pism-ii-2024-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 8, 'Biologia', 'Microorganismos como vírus, bactérias e protozoários podem causar infecções a partir da contaminação pelo contato sexual sem proteção, ou seja, são Infecções Sexualmente Transmissíveis (IST). Em relação às IST, assinale a informação CORRETA:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["A gonorreia é uma infecção bacteriana, portanto não deve ser tratada com antibióticos.", "A hepatite A, embora transmitida por vírus, não é sexualmente transmissível.", "A sífilis é uma protozoose transmitida através da placenta, de mãe para filho/a.", "A tricomoníase é uma virose geralmente assintomática nos homens.", "O vírus da AIDS é transmitido pelo compartilhamento de talheres e copos."]'::jsonb, 'B', 'Gabarito oficial: B. O gabarito oficial indica B. Ressalva científica: a afirmação de que hepatite A não tem transmissão sexual é inadequada como regra geral. O Ministério da Saúde informa transmissão fecal-oral, inclusive em práticas sexuais com contato oral-anal. Preserve-se o gabarito para correção da prova, sem usar essa frase como orientação de saúde. Referência: https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/h/hepatites-virais/hepatite-a' from public.exams where slug='pism-ii-2024-dia-2'

