insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 9, 'Biologia', 'Uma reportagem sobre agroecossistemas menciona morangueiros, plantas invasoras, luz, água e temperatura. Qual alternativa identifica componentes bióticos?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto-base resumido: práticas agrícolas afetam as relações entre os organismos e as condições físicas do ambiente.', null, '["Herbicidas, minerais e clima fazem parte do componente biótico.", "Minerais, chuva e temperatura fazem parte do componente biótico.", "Morangos e plantas invasoras fazem parte do componente biótico.", "Pesticidas e plantas invasoras fazem parte do componente abiótico.", "Plantas invasoras, fungos e bactérias fazem parte do componente abiótico."]'::jsonb, 'C', 'Gabarito oficial: C. Morangueiros e plantas invasoras são organismos vivos, portanto componentes bióticos do ecossistema. Água, luz e temperatura são componentes abióticos.' from public.exams where slug='pism-ii-2024-dia-2'

