insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 10, 'Biologia', 'Microalgas são estudadas como fonte de biomassa e insumos. Considerando a fotossíntese e sua forma de nutrição, qual alternativa está correta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

A reportagem do caderno aborda produção de biomassa a partir de microalgas.', null, '["As algas são organismos heterotróficos e possuem elevada taxa de crescimento e alta produtividade de biomassa por meio da fotossíntese.", "As algas são organismos heterotróficos e possuem alta eficiência na absorção de luz solar e na conversão de dióxido de carbono em biomassa por meio da quimiossíntese.", "As microalgas são organismos quimioautotróficos e costumam ser as mais utilizadas para a produção de biocombustíveis por realizarem fotossíntese.", "As algas são organismos autotróficos e, por realizarem quimiossíntese, crescem bem rápido, podendo completar um ciclo de crescimento e duplicar sua biomassa em poucos dias.", "As microalgas são organismos autotróficos e, por realizarem fotossíntese, podem converter energia solar em biomassa, sendo uma fonte de matéria-prima para os biocombustíveis."]'::jsonb, 'E', 'Gabarito oficial: E. Microalgas fotossintetizantes usam luz como fonte de energia e fixam carbono inorgânico, sendo fotoautotróficas capazes de produzir biomassa.' from public.exams where slug='pism-ii-2024-dia-2'

