insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 11, 'Física', 'A vazão de um rio é dada pelo produto da área da seção reta do rio pela velocidade das águas. Em um trecho brasileiro, o rio Amazonas possui uma largura de 1,5 km e profundidade média de 100 m. Neste trecho, a velocidade das águas é de 1,4 m/s. Em sua desembocadura no mar, o rio Amazonas possui uma largura de 300 km, e uma profundidade média de 50 m. Considere um modelo simplificado no qual o rio possua secção reta em formato retangular, e que não haja aumento significativo de água devido a afluentes entre os dois trechos citados. Segundo estas informações, a velocidade das águas do rio Amazonas quando chegam ao mar é', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["0,7 cm/s.", "1,4 cm/s.", "1,4 m/s.", "2,8 m/s.", "14,0 m/s."]'::jsonb, 'B', 'Gabarito oficial: B. Pela continuidade, A₁v₁ = A₂v₂. A vazão inicial é 1500·100·1,4 = 210000 m³/s. Na área de 300000·50 m², v₂ = 0,014 m/s = 1,4 cm/s.' from public.exams where slug='pism-ii-2024-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 12, 'Física', 'Sabe-se que dois líquidos A e B são imiscíveis entre si (ou seja, não se misturam) e que A é imiscível com a água. Em laboratório, mediu-se a pressão hidrostática dos líquidos A e B em função da profundidade, mostradas no gráfico a seguir. Analisando o gráfico, assinale a alternativa CORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-2-questao-12.png', '["A densidade do líquido A é de 12.000 kg/m3 .", "A densidade do líquido B é de 800 kg/m3.", "Ao ser colocado num recipiente junto com água, o líquido A fica por cima da água.", "Ao serem colocados no mesmo recipiente, o líquido A fica por cima do líquido B.", "O líquido A é 2 vezes mais denso do que o líquido B."]'::jsonb, 'B', 'Gabarito oficial: B. A pressão hidrostática cresce com a profundidade segundo p = ρgh. A inclinação da reta B no gráfico corresponde a ρB = 800 kg/m³, usando g = 10 m/s².' from public.exams where slug='pism-ii-2024-dia-2'

on conflict (exam_id,number) do update set subject=excluded.subject, text=excluded.text, support=excluded.support, support_image=excluded.support_image, options=excluded.options, answer=excluded.answer, explanation=excluded.explanation;

insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 13, 'Física', 'A figura abaixo mostra um diagrama pressão-volume de um gás ideal para as quatro fases do ciclo termodinâmico de um motor. Sabe-se que duas dessas quatro fases são isotérmicas. Considerando o trabalho realizado pelo gás, a variação de energia interna do gás e o calor fornecido ao gás em cada fase do ciclo, pode-se afirmar que durante a fase', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-2-questao-13.png', '["AB não há realização de trabalho.", "AB a energia interna diminui.", "BC o trabalho realizado é positivo.", "DA não há calor fornecido.", "DA a energia interna aumenta."]'::jsonb, 'E', 'Gabarito oficial: E. No trecho DA o volume é constante e a pressão cresce. Para gás ideal, pV = nRT implica aumento de temperatura; a energia interna também aumenta.' from public.exams where slug='pism-ii-2024-dia-2'

