insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 14, 'Física', 'Na fibra óptica da figura, nA, nN e nC são os índices de refração do ar, do núcleo e da casca. Que ordem permite a entrada da luz e a reflexão total no núcleo?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-2-questao-14.png', '["nA < nC < nN", "nA < nN < nC", "nC < nA < nN", "nC < nN < nA", "nN < nC < nA"]'::jsonb, 'A', 'Gabarito oficial: A. A reflexão total exige luz passando do núcleo para uma região de menor índice: nN > nC. A configuração indicada ainda tem nC > nA, portanto nA < nC < nN.' from public.exams where slug='pism-ii-2024-dia-2'

