insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 15, 'Física', 'De acordo com a segunda lei da termodinâmica, assinale a alternativa CORRETA.', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', null, '["Aparelhos de ar condicionado usam energia elétrica para resfriar o ar, podendo funcionar dentro de ambientes isolados termicamente.", "Com tecnologia apropriada, poderíamos aproveitar integralmente a energia contida nos combustíveis como trabalho útil.", "Um sistema termodinâmico, que emite a mesma quantidade de calor que recebe, sempre mantém sua entropia constante.", "Um veículo movido a combustão interna nunca funcionaria em ambientes tão quentes quanto o seu próprio motor.", "Uma poça de água que evapora é um exemplo de transformação termodinâmica reversível."]'::jsonb, 'D', 'Gabarito oficial: D. Uma máquina térmica precisa operar entre reservatórios de temperaturas diferentes. Não converte integralmente calor em trabalho em um ciclo, conforme a segunda lei.' from public.exams where slug='pism-ii-2024-dia-2'

