insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 16, 'História', 'Um texto de Edmund Burke critica a ruptura da Revolução Francesa e valoriza instituições e hierarquias tradicionais. A que posição política essa crítica se associa?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Excerto de Reflexões sobre a Revolução em França. Texto integral e referência no caderno.', null, '["O conservadorismo se desenvolveu a partir dos diálogos filosóficos entre intelectuais da aristocracia feudal, no contexto da Revolução Gloriosa.", "O conservadorismo promovia, simultaneamente, a defesa da aristocracia feudal e a intensificação dos valores dos jacobinos no contexto pré-revolucionário.", "O conservadorismo promovia a defesa do processo de modernização capitalista, em contrariedade com as ambições da aristocracia feudal, percebida como atrasada.", "O conservadorismo promovia uma crítica ao processo revolucionário, sendo um fenômeno marcado pela defesa dos interesses políticos e econômicos da aristocracia feudal.", "O conservadorismo criticava o processo revolucionário contra a aristocracia feudal, por entender que ele acelerava a formação dos Estados Nacionais e a concentração dos poderes."]'::jsonb, 'D', 'Gabarito oficial: D. Burke critica a ruptura revolucionária e defende a continuidade institucional e a aristocracia, expressão do conservadorismo contrário à Revolução Francesa.' from public.exams where slug='pism-ii-2024-dia-2'

