insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 17, 'História', 'Um texto histórico discute a ascensão de caudilhos na América Latina após as independências. Qual processo explica esse fenômeno?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

O texto-base relaciona organização política, elites locais e chefias militares.', null, '["das vantagens raciais dos colonos de origem hispânica e da aproximação política com o Exército brasileiro.", "das tradições coloniais de poder local e das lideranças militares surgidas no período das guerras de independência.", "das resistências dos povos nativos à colonização e das lideranças que emergiram no contexto da Guerra do Paraguai.", "das flexíveis estruturas administrativas coloniais e dos acordos políticos com os espanhóis durante os processos de independência.", "das conquistas econômicas obtidas durante o processo colonizador e as negociações políticas dos processos de independência."]'::jsonb, 'B', 'Gabarito oficial: B. O caudilhismo se relaciona à força das elites locais e à atuação de chefes militares na independência e na formação dos Estados latino-americanos.' from public.exams where slug='pism-ii-2024-dia-2'

