insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 18, 'História', 'Um discurso histórico favorável à imigração europeia atribui diferenças de valor a grupos raciais. Que interpretação explica essa proposta?', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.

Texto-base e imagem do caderno expressam ideias de branqueamento e hierarquização racial no Brasil.', null, '["Tratou-se da aplicação das políticas indigenistas, como forma de inclusão dos povos originários na sociedade brasileira.", "Foram marcadas pela ótica racista, que privilegiava a presença do imigrante europeu, como estratégia de embranquecimento da população brasileira.", "Com a abolição da Escravidão e o início das políticas indigenistas, há um desenvolvimento residual da eugenia no Brasil, criando uma democracia racial.", "As políticas de imigração foram marcadas pelo antilusitanismo e pela questão agrária, privilegiando a imigração de países como Alemanha, Itália, Líbano e Suriname.", "A eugenia foi marcada pela experiência do fim do regime escravocrata, sendo uma das inspirações para a construção da noção da pluralidade étnica da sociedade brasileira."]'::jsonb, 'B', 'Gabarito oficial: B. O discurso de branqueamento combina racismo e ideias eugenistas para defender imigração europeia e hierarquizar grupos humanos.' from public.exams where slug='pism-ii-2024-dia-2'

