insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 19, 'História', 'Observe as imagens a seguir: Disponível em: https://www.proenem.com.br/enem/historia/os-eua-no-seculo-xix-a-nacao-cresce-e-o-norte-conduz-os-caminhos-doimperialismo/acesso em 20 jun. 2023 Fonte: Vainfas, R.; Faria, S.C.; Ferreira, J. e Santos, G. Conecte, História. Vol. 2. São Paulo, Saraiva, 2018. p. 231. Elas nos ajudam a pensar na história dos Estados Unidos do século XIX como um processo marcado pela expansão e também por conflitos. A partir da observação das imagens e com base em seus conhecimentos, é CORRETO afirmar que esse processo envolveu', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-2-questao-19.png', '["a compra de alguns territórios de outros países, a anexação violenta de outros e a resistência de povos indígenas.", "a Guerra Civil Americana, a tomada de territórios pertencentes ao Canadá e a abolição da escravidão indígena.", "a guerra entre Norte e Sul, a aliança com o México e a união dos povos indígenas para expulsar os colonizadores.", "a crença no Destino Manifesto, a modernização das propriedades rurais do Norte e a catequização dos indígenas.", "a fixação da Doutrina Monroe, o avanço dos Estados Confederados em direção ao leste e o apoio dos indígenas à campanha abolicionista."]'::jsonb, 'A', 'Gabarito oficial: A. A expansão territorial dos EUA combinou compras, anexações e guerras, encontrando resistência de povos indígenas e de outras populações.' from public.exams where slug='pism-ii-2024-dia-2'

