insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)

select id, 20, 'História', 'Observe a tabela abaixo, sobre a população e a produção de café na Zona da Mata mineira entre 1822 e 1920: Fonte: LACERDA, Antonio Henrique Duarte. Economia, crescimento populacional e manumissões onerosas e gratuitas condicionais em Juiz de Fora na segunda metade do século XIX. Anais do X Seminário sobre a economia mineira, 2002, p. 3. Considerando que a economia cafeeira consolidou-se como principal atividade econômica do Império brasileiro, a análise da tabela mostra que a Zona da Mata mineira:', 'Redação adaptada para estudo; numeração e ordem das alternativas preservadas. Textos de apoio resumidos. Consulte a questão e os textos integrais no caderno oficial. Explicação autoral, não publicada pela banca.', '/pism-ii-2024-dia-2-questao-20.png', '["Teve participação continuamente decrescente na economia do Brasil durante o período imperial.", "Interrompeu o fluxo de crescimento populacional e de produção cafeeira com o fim da escravidão.", "Apresentou maior aumento populacional entre 1872 e 1890 e redução na produção cafeeira entre 1839 e 1860.", "Manteve crescimento irregular da população e da produção de café, mostrando que não havia relação entre uma coisa e outra.", "Constituiu-se como um importante polo da produção cafeeira e da urbanização do Brasil a partir da segunda metade do século XIX."]'::jsonb, 'E', 'Gabarito oficial: E. O crescimento populacional e urbano da Zona da Mata acompanha a expansão cafeeira do século XIX e a formação de polos econômicos regionais.' from public.exams where slug='pism-ii-2024-dia-2'

