commit;

select e.slug,count(q.id) as quantidade_questoes,count(q.explanation) as explicacoes from public.exams e left join public.questions q on q.exam_id=e.id where e.slug in ('pism-ii-2024-dia-1','pism-ii-2024-dia-2') group by e.slug order by e.slug;
